// Filter deals that haven't been enriched yet or are stale (>7 days old)
const deals = $('Fetch All Streak Deals').all().map(i => i.json);
const enriched = $('Fetch Existing Enrichments').all().map(i => i.json);

const enrichedMap = {};
enriched.forEach(e => {
  enrichedMap[e.box_key] = new Date(e.enriched_at);
});

const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

// Prioritize: urgent tracking (5007), IC (5011), deep dive (5003), term sheet (5004)
const PRIORITY_STAGES = new Set(['5007', '5011', '5003', '5004', '5002', '5018']);

const needsEnrichment = deals
  .filter(d => {
    if (!d.box_key) return false;
    const lastEnriched = enrichedMap[d.box_key];
    if (!lastEnriched) return true;   // Never enriched
    if (lastEnriched < sevenDaysAgo && PRIORITY_STAGES.has(d.stage_key)) return true; // Stale priority deal
    return false;
  })
  .sort((a, b) => {
    // Priority stages first
    const pa = PRIORITY_STAGES.has(a.stage_key) ? 0 : 1;
    const pb = PRIORITY_STAGES.has(b.stage_key) ? 0 : 1;
    return pa - pb;
  })
  .slice(0, 50);  // Max 50 per run to control OpenAI costs

console.log(`Enriching ${needsEnrichment.length} deals (${deals.length} total, ${Object.keys(enrichedMap).length} already enriched)`);
return needsEnrichment.map(d => ({ json: d }));

