// Merge GPT response with original deal data
const deal = $('Process One by One').first().json;
const gptRaw = $input.first().json.message.content;

let enrichment = {};
try {
  const cleaned = gptRaw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  enrichment = JSON.parse(cleaned);
} catch(e) {
  console.error('Failed to parse GPT for deal:', deal.name, e.message);
  return [{ json: { _skip: true } }];
}

return [{
  json: {
    box_key: deal.box_key,
    company_name: deal.name,
    founder_name: enrichment.founder_name || null,
    founder_background: enrichment.founder_background || null,
    co_founders: enrichment.co_founders || null,
    founder_linkedin: enrichment.founder_linkedin || null,
    website: enrichment.website || null,
    founded_year: enrichment.founded_year || null,
    employee_count: enrichment.employee_count || null,
    business_model: enrichment.business_model || null,
    product_description: enrichment.product_description || null,
    revenue: enrichment.revenue || null,
    growth_rate: enrichment.growth_rate || null,
    customers: enrichment.customers || null,
    total_raised: enrichment.total_raised || null,
    last_round: enrichment.last_round || null,
    last_round_date: enrichment.last_round_date || null,
    investors: enrichment.investors || [],
    thesis_fit_score: enrichment.thesis_fit_score || 0,
    thesis_fit_reason: enrichment.thesis_fit_reason || null,
    strengths: enrichment.strengths || [],
    risks: enrichment.risks || [],
    competitors: enrichment.competitors || [],
    moat: enrichment.moat || null,
    market_size: enrichment.market_size || null,
    market_growth: enrichment.market_growth || null,
    enriched_at: new Date().toISOString(),
    enriched_by: 'gpt-4o-mini',
    raw_response: gptRaw.substring(0, 2000)
  }
}];
